(()=>{window.flowChecks=[];const q=s=>document.querySelector(s),qa=s=>Array.from(document.querySelectorAll(s));const set=(s,v)=>{q(s).value=v;q(s).dispatchEvent(new Event('change',{bubbles:true}));};const check=(name,ok)=>{flowChecks.push({name,pass:!!ok});if(!ok)throw Error(name);};try{
q('#create-opportunity').click();set('#op-company','Jardim Comercial · fictício');set('#op-contact','Nina Exemplo');set('#op-email','nina@example.com');set('#op-phone','+55 (00) 00000-0008');set('#op-origin','Indicação');set('#op-value','7200');set('#op-notes','Primeiro contato registrado para demonstração.');q('#opportunity-form').requestSubmit();
check('Create opens new opportunity with contact and notes',q('dialog').textContent.includes('nina@example.com')&&q('dialog').textContent.includes('Primeiro contato'));let d=designState().deals.at(-1);window.flowDealId=d.id;
q('#edit-opportunity').click();set('#op-company','Jardim Comercial · revisão');set('#op-contact','Nina Revisão');set('#op-email','nina.revisao@example.com');set('#op-origin','Site');set('#op-value','7600');set('#op-stage','Qualificação');set('#op-priority','Alta');set('#op-rx','yes');set('#op-notes','Escopo e dados de contato revisados no exemplo.');q('#opportunity-form').requestSubmit();d=designState().deals.find(d=>d.id===flowDealId);
check('Edit preserves ID and updates opportunity and custom fields',d.company==='Jardim Comercial · revisão'&&d.contact==='Nina Revisão'&&d.email==='nina.revisao@example.com'&&d.origin==='Site'&&d.value===7600&&d.priority==='Alta'&&d.rx&&d.note.includes('revisados'));
check('Edited values visible in same detail',q('dialog').textContent.includes('nina.revisao@example.com')&&q('dialog').textContent.includes('revisados'));
q('#locate-opportunity').click();check('Locate shows edited card in board and correct stage',qa('.deal').length===1&&q('.deal').textContent.includes('Nina Revisão')&&q('.deal').closest('.lane').dataset.lane==='Qualificação');
return {passed:true,phase:1,checks:flowChecks};}catch(e){return {passed:false,error:String(e),checks:flowChecks};}})()
